-- QuickBooks Desktop Web Connector durable synchronization queue.
create table public.quickbooks_sync_queue(sync_job_id uuid primary key default gen_random_uuid(),entity_type text not null check(entity_type in('CUSTOMER','VENDOR','ITEM','ESTIMATE','INVOICE','PURCHASE_ORDER')),entity_id uuid not null,status text not null default'PENDING'check(status in('PENDING','PROCESSING','SYNCED','FAILED')),attempt_count int not null default 0,quickbooks_list_id text,quickbooks_txn_id text,last_error text,response_xml text,created_at timestamptz not null default now(),created_by text not null default'system',started_at timestamptz,completed_at timestamptz,updated_at timestamptz not null default now());
create unique index quickbooks_sync_one_open_job on public.quickbooks_sync_queue(entity_type,entity_id)where status in('PENDING','PROCESSING','SYNCED');
create table public.quickbooks_web_connector_sessions(ticket uuid primary key default gen_random_uuid(),username text not null,current_job_id uuid references public.quickbooks_sync_queue(sync_job_id),last_error text,company_file text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),closed_at timestamptz);
alter table public.quickbooks_sync_queue enable row level security;alter table public.quickbooks_web_connector_sessions enable row level security;create policy factory_read_qb_sync on public.quickbooks_sync_queue for select using(has_factory_role(auth.uid(),array['admin','accounts','viewer']));
create or replace function public.queue_quickbooks_sync(p_entity_type text,p_record_ids jsonb)returns int language plpgsql security definer set search_path=public as $$declare v_id text;v_count int:=0;begin if not has_factory_role(auth.uid(),array['admin','accounts'])then raise exception'not authorized';end if;if p_entity_type not in('CUSTOMER','VENDOR','ITEM','ESTIMATE','INVOICE','PURCHASE_ORDER')or jsonb_typeof(p_record_ids)<>'array'then raise exception'invalid synchronization request';end if;for v_id in select jsonb_array_elements_text(p_record_ids)loop insert into quickbooks_sync_queue(entity_type,entity_id,created_by)values(p_entity_type,v_id::uuid,auth.uid()::text)on conflict do nothing;if found then v_count:=v_count+1;end if;end loop;insert into audit_log(user_id,action,entity_type,new_value)values(auth.uid(),'QuickBooks Sync Queued','quickbooks_sync_queue',jsonb_build_object('type',p_entity_type,'queued',v_count));return v_count;end$$;
revoke all on function public.queue_quickbooks_sync(text,jsonb)from public;grant execute on function public.queue_quickbooks_sync(text,jsonb)to authenticated;
